// Extract input query parameters sent by Woops Agent Engine
const payload = $json.body || $json;
const input = payload.input || {};
const query = input.query || input.email || input.customerId || 'Sarah';

// Simulate/Fetch CRM customer record (e.g. from HubSpot / Database)
const mockCustomerDatabase = [
  {
    customerId: 'cust_98231',
    name: 'Sarah Connor',
    email: 'sarah@example.com',
    plan: 'BUSINESS',
    status: 'ACTIVE',
    lifetimeValue: 1240,
    openTickets: 0
  },
  {
    customerId: 'cust_44120',
    name: 'Alex Vance',
    email: 'alex@example.com',
    plan: 'PRO',
    status: 'ACTIVE',
    lifetimeValue: 450,
    openTickets: 1
  }
];

const match = mockCustomerDatabase.find(c => 
  c.email.toLowerCase().includes(query.toLowerCase()) || 
  c.name.toLowerCase().includes(query.toLowerCase()) || 
  c.customerId === query
) || mockCustomerDatabase[0];

// Return standard structured data response
return {
  json: {
    success: true,
    data: match
  }
};
